#include <cstdio>
#include <vector>
#include <cstring>

std::vector<long long> in, out;

int main() {
    int q;
    scanf("%d", &q);
    for (int i = 0; i < q; ++i) {
        char op[16];
        scanf("%s", op);
        if (strcmp(op, "push") == 0) {
            long long x;
            scanf("%lld", &x);
            in.push_back(x);
        } else if (strcmp(op, "pop") == 0) {
            if (out.empty()) {
                while (!in.empty()) { out.push_back(in.back()); in.pop_back(); }
            }
            printf("%lld\n", out.back());
            out.pop_back();
        } else if (strcmp(op, "peek") == 0) {
            if (out.empty()) {
                while (!in.empty()) { out.push_back(in.back()); in.pop_back(); }
            }
            printf("%lld\n", out.back());
        } else if (strcmp(op, "size") == 0) {
            printf("%d\n", (int)(in.size() + out.size()));
        }
    }
    return 0;
}
